mapper.select:
SELECT o.id AS observation_id, o.report_id, o.examination_date, o.original_value, o.result_kind,
       o.numeric_value, o.unit_text, o.reference_text, o.reference_low, o.reference_high, o.abnormal_flag,
       o.specimen_text, o.method_text

  AND o.metric_definition_id = #{metricDefinitionId}
  AND o.examination_date <= #{to}
ORDER BY o.examination_date, o.id
